import pendulum
from airflow.decorators import dag, task

@dag(schedule="@daily", start_date=pendulum.datetime(2026, 1, 1, tz="UTC"), catchup=False)
def offers_per_country():
    @task
    def list_files(ds=None):
        # small value through XCom: paths, not data
        return [f"s3://raw/offers/{ds}/{c}.json" for c in ["fr", "be", "ch"]]

    @task(max_active_tis_per_dag=2)
    def load(path: str, table: str):
        print(f"loading {path} into {table}")
        return path

    @task
    def report(paths):
        print(f"{len(list(paths))} files loaded")

    loaded = load.partial(table="raw_offers").expand(path=list_files())
    report(loaded)

