import pendulum
from airflow.decorators import dag, task
from airflow.datasets import Dataset  # Airflow 3: from airflow.sdk import Asset
from airflow.providers.amazon.aws.sensors.s3 import S3KeySensor

offers_curated = Dataset("s3://curated/offers/")

@dag(schedule="0 6 * * *", start_date=pendulum.datetime(2026, 1, 1, tz="UTC"), catchup=False)
def ingest_offers():
    wait_file = S3KeySensor(
        task_id="wait_file",
        bucket_name="raw",
        bucket_key="offers/{{ ds }}/_SUCCESS",
        aws_conn_id="aws_raw",
        deferrable=True,          # wait in the triggerer, not on a worker
        poke_interval=300,
        timeout=6 * 60 * 60,      # give up after 6 hours
    )

    @task(outlets=[offers_curated])
    def load():
        print("load offers")

    wait_file >> load()

ingest_offers()

@dag(schedule=[offers_curated], start_date=pendulum.datetime(2026, 1, 1, tz="UTC"), catchup=False)
def offers_reporting():
    @task
    def refresh():
        print("refresh dashboards")
    refresh()

offers_reporting()

